import csv, glob, collections
rows=[]
for f in sorted(glob.glob('data/transactions_*.csv')):
    with open(f,newline='') as fh:
        r=csv.DictReader(fh)
        for i,x in enumerate(r):
            x['_file']=f; x['_line']=i+2
            rows.append(x)
print('rows',len(rows))
nums=[]
for x in rows:
    try:nums.append((float(x['amount']),x))
    except Exception as e: print('bad',x,e)
nums.sort(key=lambda t:t[0])
print('min max',nums[0][0],nums[-1][0])
for n,x in nums:
    if abs(n)>500:
        print(x['_file'],x['_line'],x['date'],x['merchant'],x['amount'],x['category'])
print('blank cat',sum(1 for x in rows if not x['category'].strip()))
print('cat existing',collections.Counter(x['category'].strip() or '<blank>' for x in rows))
pos=sorted(n for n,x in nums if n>0)
neg=sorted(n for n,x in nums if n<0)
print('pos quartiles',pos[len(pos)//4],pos[len(pos)//2],pos[3*len(pos)//4],pos[-10:])
print('neg count',len(neg), neg[:5], neg[-5:])
for n in ['4999.99','912.34','785.0','785.00']:
    hits=[(x['_file'],x['_line'],x['date'],x['merchant'],x['amount']) for x in rows if x['amount']==n]
    print(n,hits)
for fmt in ['4999.99','912.34','785.00','785.0']:
    target=float(fmt)
    hits=[(x['_file'],x['_line'],x['date'],x['merchant'],x['amount']) for x in rows if abs(float(x['amount'])-target)<0.005]
    print('near',fmt,hits)
PY"}

